# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
W=[
E('annoy','/əˈnɔɪ/','使烦恼；惹恼；打扰','不停碰到人的耐心，让他觉得烦。','经古法语 anoier／anuier 来自晚期拉丁 inodiare 使人厌烦，与拉丁 in odio 令人憎恶、odium 厌恶相关。英语早期也有伤害、困扰的较强意思。',[['拉丁 odium／in odio → 晚期拉丁 inodiare','厌恶 → 使人厌恶、困扰'],['古法语 anoier／anuier → 英语 annoy','烦扰、惹恼']],'日常 annoy 往往不用到仇恨那么重：嗡嗡声、插话、迟到，都能 annoy someone。常见句型是某事 annoys me，烦人的事做主语，感到烦的人放在后面。','annoy someone；It annoys me that…；annoy someone by doing something。','hate 是讨厌或憎恨；annoy 说引起烦躁。历史上与厌恶有关，不表示每次 annoyed 都是在仇恨别人。',('The constant clicking noise annoyed everyone in the room.','不停的咔嗒声让屋里所有人都很烦。'),('It annoys me when people interrupt before I finish speaking.','别人没等我说完就插话，会让我烦躁。'),sources=['https://www.etymonline.com/word/annoy','https://en.wiktionary.org/wiki/annoy#English']),
E('annoying','/əˈnɔɪɪŋ/','令人恼火的；烦人的','站在事情或人的一边看：它正在制造烦躁。','annoy + -ing，可以是现在分词，也可作形容词表示使人烦的。',[['英语 annoy','使别人烦恼'],['英语 annoying','正在烦扰；令人烦的']],'an annoying habit 是惹人烦的习惯。He is annoying 可以评价他很烦人；He is annoying his sister 则是他正在招惹妹妹，后面带了动作对象。','an annoying noise；an annoying habit；find something annoying；annoying someone。','annoying 是让别人烦；annoyed 是自己感到烦。I am annoying 和 I am annoyed 表达的方向完全不同。',('The app makes an annoying sound every time a message arrives.','这个应用每来一条消息都会发出烦人的声音。'),('I find it annoying when the video pauses every few seconds.','视频每隔几秒就暂停一下，我觉得很烦。'),sources=['https://en.wiktionary.org/wiki/annoying#English']),
E('annoyed','/əˈnɔɪd/','恼火的；感到烦的；被惹恼的','站在被影响的人这边看：耐心已经被磨掉了一些。','annoy + -ed，是过去式、过去分词，也可用作描写情绪的形容词；y 前是元音，拼写保留 y。',[['英语 annoy','惹人烦'],['英语 annoyed','惹恼了；被惹恼、感到烦的']],'I was annoyed with him 是我对他有点生气；annoyed about the delay 是为延误而烦。它可以从轻微不快到明显恼火，通常没有 furious 那么强烈。','annoyed with someone；annoyed about something；annoyed at the delay；look annoyed。','annoyed 描写感受者，annoying 描写造成感受的事物。The annoying noise made me annoyed 虽略重复，却把两者方向摆得很清楚。',('She was annoyed with herself for forgetting the appointment.','她因为忘记预约而生自己的气。'),('He looked annoyed when the meeting was postponed again.','会议又一次推迟时，他显得很恼火。'),sources=['https://en.wiktionary.org/wiki/annoyed#English','https://www.etymonline.com/word/annoy']),
E('annoyance','/əˈnɔɪəns/','烦恼；恼怒；烦人的事物','既可以是心里那股烦，也可以是让你烦的那个小麻烦。','经中古英语 anoyaunce 来自古法语 anoiance／anuiance，与 anuier 烦扰相关。现代可以联系 annoy + -ance，但名词本身沿法语路线传入。',[['古法语 anuier → anoiance／anuiance','烦扰 → 烦恼、困扰'],['中古英语 anoyaunce → annoyance','烦躁情绪；引起烦躁的事物']],'to my annoyance 是让我烦恼的是；a minor annoyance 是一个小麻烦。前者指情绪，通常不可数；后者指具体烦心事，可以用 a 或复数。','to someone’s annoyance；show annoyance；a minor annoyance；a source of annoyance。','anger 更直接说愤怒；annoyance 常是受打扰后的烦躁。inconvenience 强调不方便，未必强调情绪。',('To my annoyance, the printer ran out of paper halfway through.','让我恼火的是，打印到一半，打印机没纸了。'),('The loose handle was a minor annoyance rather than a serious problem.','松动的把手只是个小麻烦，算不上严重问题。'),sources=['https://en.wiktionary.org/wiki/annoyance#English']),
E('odious','英 /ˈəʊdiəs/；美 /ˈoʊdiəs/','令人憎恶的；讨厌透顶的','不只是有点烦，而是让人强烈反感、不愿接近。','拉丁 odium 厌恶 → odiosus 令人厌恶的，经古法语 odieus 等形式或直接借入英语。',[['拉丁 odium → odiosus','厌恶 → 令人厌恶的'],['法语 odieus／拉丁借入 → 英语 odious','可憎、令人强烈反感']],'an odious person 是极讨厌的人，an odious practice 是令人憎恶的做法。语气相当重，常带道德厌恶或强烈轻蔑。词里没有 odor 的气味来源，虽然两者看起来相似。','an odious character；an odious practice；an odious comparison。','annoying 可以只是小烦人；odious 强得多。odorous 与气味有关，odious 与厌恶有关。',('The novel’s villain is an odious man who exploits everyone around him.','小说里的反派是个可憎的人，利用身边的每一个人。'),('She rejected the odious idea that some lives mattered less than others.','她拒绝接受那种认为某些人的生命更不重要的可憎观念。'),sources=['https://www.etymonline.com/word/odious','https://en.wiktionary.org/wiki/odious#English']),
E('odium','英 /ˈəʊdiəm/；美 /ˈoʊdiəm/','憎恶；恶名引来的鄙弃','某种行为激起强烈厌恶，那股恶感又落到行为者身上。','直接借自拉丁 odium 憎恨、恶意，与 odi 我恨、odisse 恨相关。英语既说憎恶，也说招人憎恶的处境。',[['拉丁 odi／odisse 与 odium','恨；憎恨、恶意'],['英语 odium','憎恶；因行为受到的厌弃']],'public odium 是公众的鄙弃；incur odium 是招来恶感。它很书面，阅读评论、历史文章时更常见。别只背成自己心里的恨：the odium attached to a policy 可以是某项政策招来的恶名和反感。','public odium；incur odium；the odium attached to something。','hatred 是一般的强烈憎恨；odium 常带公众评价、恶名或受鄙弃的意味。日常表达通常直接用 hate、dislike 或 anger。',('The scandal brought public odium upon the company.','丑闻使这家公司受到公众的鄙弃。'),('He wanted no share in the odium attached to the decision.','他不愿承担那项决定招来的恶名。'),sources=['https://www.etymonline.com/word/odium','https://en.wiktionary.org/wiki/odium#English']),
E('odiously','英 /ˈəʊdiəsli/；美 /ˈoʊdiəsli/','令人憎恶地；讨厌至极地','某种做法或态度糟糕得让人强烈反感。','odious + -ly，表示以令人憎恶的方式，或强调某种性质十分讨厌。',[['英语 odious','令人憎恶的'],['英语 odiously','以令人憎恶的方式；令人厌恶地']],'behave odiously 是行为十分可憎；odiously smug 是自鸣得意到让人恶心。这个副词较书面，评价很重，不能只把它当作一个普通的 very。','behave odiously；odiously smug；odiously cruel。','odiously 修饰动作或性质；odious 直接修饰名词。annoyingly 的情绪通常轻得多。',('He behaved odiously toward the waiter.','他对服务员的态度十分可憎。'),('Her opponent sounded odiously smug after the victory.','获胜后，她的对手说话得意得令人反感。'),sources=['https://en.wiktionary.org/wiki/odiously#English','https://dictionary.cambridge.org/pronunciation/english/odiously']),
E('ennui','英 /ɒnˈwiː/；美 /ɑːnˈwiː/','倦怠；百无聊赖','不是没空干活，而是觉得什么都提不起劲。','借自法语 ennui，来自古法语 enui，与产生 annoy 的法语动词同支。英语较晚再次借入这个法语名词，保留了更接近法语的读音。',[['古法语 enoiier／anuier 与名词 enui','烦扰；烦闷'],['法语 ennui → 英语 ennui','无聊、倦怠、对生活缺乏兴趣']],'ennui 常用于文学或评论，写一种持续的精神乏味：日子不一定艰难，但每天都像复制，什么都让人无精打采。它不是今天专门的医学诊断名称，也不等于所有疲劳。','a sense of ennui；suffer from ennui；escape the ennui of routine。','boredom 是更日常的无聊；ennui 更书面，常带对生活提不起兴趣的倦怠。annoyance 多是被某事惹烦。',('The novel captures the ennui of a life without purpose.','这部小说描写了没有目标的生活带来的倦怠。'),('She travelled in an effort to escape the ennui of her routine.','她去旅行，想摆脱日复一日生活的百无聊赖。'),sources=['https://www.etymonline.com/word/ennui','https://en.wiktionary.org/wiki/ennui#English'])]
ROOT=dict(id='C0860',meaning='厌恶；憎恨',core='ODI = HATE',image='一条路线保留强烈厌恶，成为 odious；另一条经过法语变化，成为日常的 annoy 惹人烦。',intro='拉丁 odium 表示厌恶、憎恨，与 odi／odisse 恨相关。英语既有保留 odi- 的借词，也有拼写已经大变的 annoy 和 ennui。词源相同，现代情绪强度并不相同。',forms='odium → odiosus → 法语／英语 odious → odiously；拉丁 odium → 英语 odium；in odio／inodiare → 古法语 anuier → annoy；法语名词支线 → annoyance、ennui。',branches=[['日常的烦躁','annoy；annoying；annoyed；annoyance'],['强烈的憎恶','odious；odium；odiously'],['无聊与倦怠','ennui']],contrasts='不要把词根义当成所有后代的强度：an annoying noise 只是烦人的声音，不是仇恨的声音。annoying 描写原因，annoyed 描写感受者；ennui 则转到倦怠和无聊。',practice='The delay was annoying, but she was only mildly annoyed.\n\n这次延误确实烦人，不过她只是有一点不高兴。',words=[x['word'] for x in W],exclude={})
if __name__=='__main__':
 for name,data in [('roots_odi',[ROOT]),('words_odi',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(x['examples']) for x in W))
